"""Wi-Fi Audio Streaming Voice AI Controller (PC)"""
import io
import requests
import speech_recognition as sr

ESP_IP = "192.168.0.50"  # ESP32 IP
r = sr.Recognizer()
CHUNK = 16000 * 2 * 2    # 2s (16kHz, 16-bit mono)

with requests.get(f"http://{ESP_IP}:8081/", stream=True) as resp:
    resp.raw.read(44)  # Skip WAV header
    while True:
        pcm = resp.raw.read(CHUNK)
        if not pcm:
            break
        try:
            text = r.recognize_google(sr.AudioData(pcm, 16000, 2), language="en-US").lower()
            print("Voice:", text)

            action = None
            if any(w in text for w in ("go", "forward")):
                action = "GO"
            elif "stop" in text:
                action = "STOP"
            elif "dance" in text:
                action = "DANCE"

            if action:
                requests.get(f"http://{ESP_IP}:8081/ai", params={"action": action}, timeout=0.5)
        except sr.UnknownValueError:
            pass
